import {mountAdminNavigation,bindAdminMenu} from './admin-navigation.mjs';
import {automationPanel} from './admin-automation.mjs';
import {renderWorkQueue,queueCounts} from './admin-work-queue.mjs';
import {orderList} from './admin-order-list.mjs';
import {mockupsForPfOrder,mockupsForCheckout,appendMockupOverview,appendMockup} from './admin-mockups.mjs?v=4';
import {renderCompanies} from './admin-companies.mjs';
import {proofQueueLabel} from './proof-status.mjs';
import {renderStatistics} from './admin-statistics.mjs';
import {renderProducts} from './admin-products.mjs?v=4';
const $=id=>document.getElementById(id),content=$('content');let orders=[],checkouts=[],marketing=[],withdrawals=[],shipmentMails=[],view='overview';
const statusText={prepared:'Klar til PF',confirmed:'PF har bekræftet ordren',gateway_accepted:'PF har modtaget',awaiting_proof:'Afventer korrektur',proof_received:'Til gennemgang',approval_pending_pf:'Afventer PF-kvittering',revision_requested:'Ændring ønsket',approval_recorded:'PF-godkendelse registreret',processing:'Under behandling',shipped:'Afsendt',needs_attention:'Kræver opmærksomhed',needs_reconciliation:'Kræver afstemning',cancelled:'Annulleret'};
function el(tag,text,className){const node=document.createElement(tag);if(text!==undefined)node.textContent=String(text);if(className)node.className=className;return node;}
function link(text,href,light=false){const a=el('a',text,'action'+(light?' light':''));a.href=href;return a;}
function panel(title){const item=el('section',undefined,'panel');item.append(el('h2',title));return item;}
async function api(path,method='GET',body){const response=await fetch(path,{method,credentials:'same-origin',headers:{...(method==='POST'?{'X-Smerch-Admin':'1'}:{}),...(body?{'Content-Type':'application/json'}:{})},body:body?JSON.stringify(body):undefined,cache:'no-store'});if(!response.ok){let data;try{data=await response.json();}catch{}throw Error(data?.error||`HTTP ${response.status}`);}return response;}
function showLogin(){document.getElementById('login-view').hidden=false;document.getElementById('admin-app').hidden=true;}
function showApp(){document.getElementById('login-view').hidden=true;document.getElementById('admin-app').hidden=false;}
function render(){const title={actions:'Kræver handling',production:'Produktion',deliveries:'Leveringer',blocked:'Fejl og mangler',automation:'Automatik og beskeder',companies:'Virksomheder',statistics:'Statistik',products:'Produkter',overview:'I dag',proofs:'Korrekturer',orders:'Alle ordrer',integration:'PF-integration',marketing:'Marketingvalg',withdrawals:'Fortrydelser'}[view];$('page-title').textContent=title;navigation.update(view,queueCounts(orders,checkouts,shipmentMails));document.title=title+' · Smerch';content.replaceChildren();
 if(view==='automation'){automationPanel(content,api);return;}
 if(['overview','actions','production','deliveries','blocked','proofs'].includes(view)){renderWorkQueue(content,orders,checkouts,view,shipmentMails);return;}
 if(view==='statistics'){renderStatistics(content,api);return;}
 if(view==='companies'){renderCompanies(content,api);return;}
 if(view==='products'){renderProducts(content,api);return;}
 if(view==='marketing'){const box=panel('Registrerede marketingvalg');box.append(el('p','Kun aktive tilvalg må bruges, og kun til den valgte kanal og de beskrevne emner. Kontrollér samtykkets gyldighed og seneste afmeldinger før hver udsendelse. Denne side sender ikke marketing.','intro'));for(const record of marketing){const item=el('div',undefined,'order-card');item.append(el('strong',record.address),el('p',`${record.channel==='email'?'E-mail':'SMS'} · ${record.active?'Tilmeldt':'Afmeldt'} · ${new Date(record.updatedAt).toLocaleString('da-DK')}`));const details=el('details'),summary=el('summary','Samtykkehistorik');details.append(summary);for(const event of record.events)details.append(el('p',`${event.at} · ${event.type==='consent'?'Tilmelding':'Afmelding'}${event.text?' · '+event.text:''}`));item.append(details);box.append(item);}if(!marketing.length)box.append(el('p','Ingen tilmeldinger endnu.'));content.append(box);return;}
 if(view==='withdrawals'){const box=panel('Modtagne fortrydelsesmeddelelser');box.append(el('p','Registreringen er ikke en automatisk annullering eller refundering. Behandl meddelelsen og overhold fristerne.'));for(const record of withdrawals){const item=el('div',undefined,'order-card');item.append(el('strong',record.orderReference),el('p',`${record.name} · ${record.email} · ${new Date(record.receivedAt).toLocaleString('da-DK')}`),el('p',record.items||'Hele ordren'),el('p',record.emailStatus==='sent'?'Kvittering sendt':'E-mailkvittering afventer mailforbindelse'));box.append(item);}if(!withdrawals.length)box.append(el('p','Ingen meddelelser endnu.'));content.append(box);return;}
 if(view==='orders'){content.append(orderList(orders,checkouts));return;}
 const box=panel('Status på PF-forbindelsen');box.append(el('p','PF’s ordre-Gateway, statusbeskeder og korrekturindbakke er adskilte trin. Automatisk korrekturgodkendelse kræver, at PF oplyser og aktiverer den konkrete kanal.'));api('/api/pf-orders/status').then(response=>response.json()).then(result=>{const state=el('p',result.ready?`Gateway: klar (${result.mode})`:`Gateway: ikke klar (${result.mode||'off'})`,'status '+(result.ready?'ready':'pending'));box.append(state);if(result.missing?.length){const list=el('ul');for(const name of result.missing)list.append(el('li',name));box.append(el('p','Mangler fra PF eller serveropsætning:'),list);}if(result.nextStep)box.append(el('p',result.nextStep,'muted'));if(result.ready&&result.mode==='test')box.append(link('Opret Gateway-testordre →','/admin/pf-orders'));}).catch(()=>box.append(el('p','Gateway-status kunne ikke hentes.','status pending')));box.append(el('p','Interne godkendelser frigiver ikke produktionen, før PF faktisk har kvitteret.','muted'));content.append(box);
}
async function load(){try{const session=await(await api('/api/admin/session')).json();if(session.role&&session.role!=='administrator'){location.href='/backoffice.html';return;}[orders,checkouts,marketing,withdrawals]=await Promise.all([api('/api/pf-orders').then(r=>r.json()),api('/api/admin/checkouts').then(r=>r.json()),api('/api/admin/marketing').then(r=>r.json()),api('/api/admin/withdrawals').then(r=>r.json())]);const automation=await(await api('/api/pf-orders/automation-settings')).json();shipmentMails=automation.shipments||[];showApp();render();$('feedback').textContent='';}catch(error){$('feedback').textContent=error.message;if(error.message.includes('Administratoradgang'))showLogin();}}
const menu=bindAdminMenu({shell:$('admin-app'),button:$('menu-toggle'),sidebar:$('admin-nav')}),navigation=mountAdminNavigation($('admin-nav'),{navigate:key=>{view=key;history.pushState(null,'',key==='overview'?'/admin':'/admin#'+key);menu.close();render();$('page-title').focus();},onLogout:async()=>{try{await api('/api/admin/logout','POST');}finally{location.assign('/');}}});$('page-title').tabIndex=-1;
document.getElementById('admin-login').addEventListener('submit',async event=>{event.preventDefault();const form=event.currentTarget,data=new FormData(form);try{await api('/api/admin/login','POST',{username:String(data.get('username')||'').trim(),password:String(data.get('password')||'')});form.elements.password.value='';await load();}catch(error){form.elements.password.value='';$('login-error').textContent=error.message;}});
$('refresh').onclick=()=>{document.querySelector('.page-actions').open=false;load();};
view=['actions','production','deliveries','blocked','automation','companies','statistics','products','proofs','orders','integration','marketing','withdrawals'].includes(location.hash.slice(1))?location.hash.slice(1):'overview';if(view==='actions')view='overview';api('/api/admin/session').then(response=>response.json()).then(state=>state.authenticated?load():showLogin()).catch(showLogin);

window.addEventListener('hashchange',()=>{const requested=location.hash.slice(1)==='actions'?'overview':location.hash.slice(1)||'overview';if(['overview','actions','production','deliveries','blocked','automation','orders','proofs','companies','statistics','products','integration','marketing','withdrawals'].includes(requested)){view=requested;render();}});
